from collections import deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    q=[(r,c)]; seen.add((r,c)); pts=[]
    while q:
     a,b=q.pop(); pts.append((a,b))
     for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
      if 0<=x<h and 0<=y<w and g[x][y] and (x,y) not in seen: seen.add((x,y));q.append((x,y))
    out.append(pts)
 return out
